\label{thm:informal}
Given a distribution $D$ consisting of strings of tokens from an alphabet $\Sigma$, for any $\delta$:
\begin{itemize}
    \item Given an efficiently computable $\delta$-optimal autoregressive model for $D$, one can construct an efficiently computable monotone compression scheme which is $(\delta+2)$-optimal with respect to $D$.\footnote{The additive gap of 2 in this result, and later Corollary \ref{cor:informal}, arises from the use of arithmetic encoding in the transformation from autoregressive modeling to compression; some additive loss is inevitable as no compression scheme can achieve zero compression loss without strict conditions on the distribution $D$.}
    \item Given an efficiently computable monotone compression scheme which is $\delta$-optimal with respect to $D$, one can construct a $\delta$-optimal autoregressive model for $D$.                                                                                                                                                                                                                                     
\end{itemize}

\label{cor:informal}
Given a family of distributions $\mathcal{D}$, the following are equivalent for any function $k(n)$ (to within an additive gap of 2):
\begin{itemize}
    \item $\mathcal{D}$ cannot be efficiently \emph{monotonically} compressed to length $k(n)$.
    \item $\mathcal{D}$ has next-bit pseudoentropy at least $k(n)$.
\end{itemize}

\label{def:compression}
Given finite families of alphabets $\Sigma = \lbrace \Sigma_n \rbrace_{n \in \mathbb{N}}$ and $\Sigma' = \lbrace \Sigma'_n \rbrace_{n \in \mathbb{N}}$ where $|\Sigma_n|$ and $|\Sigma'_n|$ are polynomial in $n$, functions $m(\cdot), \ell(\cdot)$ where $m(n)$ is polynomial in $n$, and an ensemble of distributions $\mathcal{D} = \lbrace D_n \rbrace_{n \in \mathbb{N}}$, where $\sup(D_n) \subseteq \Sigma_n^{m(n)}$, we say that a family of injective functions $\mathsf{Enc} = \lbrace \mathsf{Enc}_n \rbrace_{n \in \mathbb{N}}$ is an \textbf{encoding}, or \textbf{compression scheme}\footnote{Oftentimes the term ``compression" is used to indicate strictly prefix-free encodings; however, we consider only prefix-free encodings anyway in our results.}. $\mathsf{Enc}$ \textbf{compresses $\mathcal{D}$ to length} $\ell(\cdot)$ if, for any $n \in \mathbb{N}$, $\mathsf{Enc}_n : \Sigma_n^{m(n)} \rightarrow \Sigma'^*_n$ is such that
\[ \mathbf{E}_{x \leftarrow D_n} [\text{len}(\mathsf{Enc}_n(x))] \leq \ell(n) \]

\label{cor:shannon}
Given finite alphabets $\Sigma$ and $\Sigma'$ and distribution $D$ over $\Sigma$, let $\ell^*(D)$ be the minimal expected length $\mathbf{E}_{x \leftarrow D} [\text{len}(\mathsf{Enc}(x))]$ over any prefix-free encoding $\mathsf{Enc} : \Sigma \rightarrow \Sigma'$. Then:
\[ \frac{H(D)}{\log |\Sigma'|} \leq \ell^*(D) \]

By the definition of KL-divergence:
\begin{align*}
 KL(D \; || \; D') &\; = \mathbf{E}_{x \leftarrow D} [\log (1/D'(x))] - \mathbf{E}_{x \leftarrow D} [\log (1/D(x))] \\
&\; \geq (\mathbf{E}_{x \leftarrow D} [\text{len}(\mathsf{Enc}(x))] - \alpha) - H(D) \\
\end{align*}
which directly implies the conclusion.

\label{fact:cross-kl}
For any distributions $D_1, D_2$:
\[ H(D_1, D_2) = KL(D_1 || D_2) + H(D_1) \]

\begin{align*}
        H(D_1, D_2) &= - \sum_{x \in \sup(D_1)} D_1(x) \log D_2(x) = \sum_{x \in \sup(D_1)} D_1(x) \log \frac{D_1(x)}{D_2(x)} - \sum_{x \in \sup(D_1)} D_1(x) \log D_1(x) \\&=   KL(D_1 || D_2) + H(D_1). 
    \end{align*}

\label{clm:efficient-cumulative}
Given a polynomial-sized alphabet family $\Sigma = \lbrace \Sigma_n \rbrace_{n \in \mathbb{N}}$ with lexicographical ordering $\prec$, polynomial maximum length $m(\cdot)$, and family of autoregressive models $\mathcal{M} = \lbrace \mathcal{M}_n \rbrace_{n \in \mathbb{N}}$ over $\Sigma_n^{m(n)}$, the following statements are equivalent:

\begin{enumerate}
    \item For any $t \in \Sigma_n^{m(n)}$, $\mathcal{M}_n(t_i \; | \; t_{<i})$ is efficiently computable on all prefixes with $\Pr_{x \leftarrow D_{\mathcal{M}_n}}[x_{< i} = t_{< i}] > 0$.
    \item For any $n \in \mathbb{N}$ and $a \in \Sigma_n^{m(n)}$, the cumulative distribution function $\Pr_{x \leftarrow D_{\mathcal{M}_n}}[x \preceq a]$ is efficiently computable.
\end{enumerate}

\label{lemma:llm-compression}
Let $\mathcal{D}$ be a distribution over $\Sigma^m$,  $\mathcal{M}$ be an autoregressive model with induced distribution $D_\mathcal{M}$, and $\mathsf{Enc}$ be a prefix-free encoding scheme such that there exists constant $\alpha$ for which, for any $x\in \sup(\mathcal{D})$, $\text{len}(\mathsf{Enc}(x)) \leq \log(1/D_\mathcal{M}(x)) + \alpha$. Then, if $\mathcal{M}$ is $\delta$-optimal with respect to $D$, $\mathsf{Enc}$ satisfies:
\[ \mathbf{E}_{x \leftarrow D} [\text{len}(\mathsf{Enc}(x))] \leq H(D) + \delta + \alpha \]

\label{thm:llm-compression-arithmetic}
Given a polynomial-sized alphabet family $\Sigma = \lbrace \Sigma_n \rbrace_{n \in \mathbb{N}}$ with respective ordering $\lbrace \prec_n \rbrace_{n \in \mathbb{N}}$ and polynomial maximum length $m(\cdot)$, there exists an oracle-aided algorithm $\mathsf{Enc}^{(\cdot)}$ so that, for any family of distributions $\mathcal{D} = \lbrace D_n \rbrace_{n \in \mathbb{N}}$, family of autoregressive models $\mathcal{M} = \lbrace \mathcal{M}_n \rbrace_{n \in \mathbb{N}}$ over $\Sigma_n^{m(n)}$ where $\mathcal{M}_n(t_i \; | \; t_{<i})$ is efficiently computable for any $t \in \Sigma_n^{\leq m(n)}$ and induces a distribution $D_{\mathcal{M}_n}$ such that there exists polynomial\footnote{We note that there must exist such a polynomial $\ell(\cdot)$ for any efficiently computable autoregressive model family $\mathcal{M}$, since all next token probabilities must be polynomial-length representable for efficient computability. As noted in the remark following Claim \ref{clm:arithmetic-properties}, one can remove the requirement for such an a priori bound, but at the cost of an exponentially small $\epsilon(n)$ to the encoding length.} $\ell(\cdot)$ for which $- \log(D_{\mathcal{M}_n}(x)) \leq \ell(n)$ for all $x \in \sup(D_{\mathcal{M}_n})$, and function $\delta(\cdot)$ so that, for any $n \in \mathbb{N}$, $\mathcal{M}_n$ is $\delta(n)$-optimal with respect to $D_n$, the family of encodings $\mathsf{Enc} = \lbrace \mathsf{Enc}^{\mathcal{M}_n, \prec_n}(1^n, \ell(n), \cdot) \rbrace_{n \in \mathbb{N}}$ is prefix-free, monotone (with respect to $\prec$), and efficient, and additionally, for any $n \in \mathbb{N}$:
\[ \mathbf{E}_{x \leftarrow D_n} [\text{len}(\mathsf{Enc}_n(x))] \leq H(D_n) + \delta(n) + 2 \]

\label{thm:compression-llm}
Given a polynomial-sized alphabet family $\Sigma = \lbrace \Sigma_n \rbrace_{n \in \mathbb{N}}$ and polynomial maximum length $m(\cdot)$, there exists an oracle-aided algorithm $\mathcal{M}^{(\cdot)}$ such that, for any family of distributions $\mathcal{D} = \lbrace D_n \rbrace_{n \in \mathbb{N}}$, any function $\delta(\cdot)$, and any prefix-free, monotone (with respect to an ordering $\lbrace \prec_n \rbrace_{n \in \mathbb{N}}$) and efficiently encodable family of encodings $\mathsf{Enc} = \lbrace \mathsf{Enc}_n \rbrace_{n \in \mathbb{N}}$ such that, for any $n \in \mathbb{N}$,
\[ \mathbf{E}_{x \leftarrow D_n} [\text{len}(\mathsf{Enc}_{n}(x))] \leq H(D_n) + \delta(n) \] $\mathcal{M}^{(\cdot)}$ defines a family of autoregressive models $\lbrace \mathcal{M}_n \rbrace_{n \in \mathbb{N}}$ where, for any $n \in \mathbb{N}$ and $t \in \Sigma_n^{\leq m(n)}$, $\mathcal{M}_n(t_i \; | \; t_{<i})$ is given by $\mathcal{M}^{\mathsf{Enc}_n, \prec_n}(1^n,  t_i, t_{<i})$, $\mathcal{M}^{(\cdot)}$ is efficiently computable, and the respective model $\mathcal{M}_n$ is $\delta(n)$-optimal with respect to $D_n$.

As the existence of one-way functions implies the existence of PRGs (respectively, infinitely-often OWFs imply \emph{infinitely-often PRGs}, or PRGs where the condition holds for only infinitely many $n \in \mathbb{N}$), let $\mathcal{G} = \lbrace g_n \rbrace_{n \in \mathbb{N}}$ be a PRG with output length $\ell(n) = 2n$. Take our alphabet of tokens to be $\Sigma = \lbrace 0,1 \rbrace$. Let $\mathcal{D}$ be given by $D_n = \lbrace x \leftarrow U_n : (g_n(x), x) \rbrace$. Let $\mathsf{Enc}$ be given by $\mathsf{Enc}_n(g_n(x), x) = x$.\footnote{That is, simply take the last $n$ bits of the input. This can be efficiently decoded as well by simply computing $g_n(x)$; one can extend it to the full domain of arbitrary $3n$-bit inputs by letting $\mathsf{Enc}_n(y, x) = y || x$ if $y \neq g_n(x)$.} Clearly, $\mathsf{Enc}$ satisfies prefix-freeness (since every codeword has the same length), efficient encoding and decoding, and has $\mathbf{E}_{x \leftarrow D_n} [\text{len}(\mathsf{Enc}_{n}(x))] = H(D_n) = n$.

Now fix $\epsilon > 0$ and assume for the sake of contradiction that there exists a family of autoregressive models $\lbrace \mathcal{M}_n \rbrace_{n \in \mathbb{N}}$ such that $KL(D_n \; || \; D_{\mathcal{M}_n}) < (1 - \epsilon)n$ for infinitely many (resp., all sufficiently large) $n \in \mathbb{N}$. We use this to construct a distinguisher $\mathcal{A}$ 

as follows: Take constant $c > \log (2/\epsilon)$, and, given an input $y$ (which will either be drawn as $U_{2n}$ or as $g_n(U_n)$), define $D_{\mathcal{M}_n}(y, *)$                                                                                                              
as the probability for the first $2n$ bits of an output from $\mathcal{M}_n$ to be equal to $y$, and let $\mathcal{A}$ output $1$ when $D_{\mathcal{M}_n}(y, *) \geq 2^{c-2n}$ and $0$ otherwise. We make the following claims to complete the proof by contradiction:

\begin{claim*}
$\text{Pr} \left[y \leftarrow U_{2n} : \mathcal{A}(y) = 1 \right] \leq 2^{-c}$.
\end{claim*}

\begin{proof}
$\mathbf{E}_{y \leftarrow U_{2n}}[D_{\mathcal{M}_n}(y, *)] = 2^{-2n}$, so this follows from Markov's inequality.
\end{proof}

\begin{claim*}
For any constant $\epsilon' > 0$, $\text{Pr} \left[x \leftarrow U_{n} : \mathcal{A}(g_n(x)) = 1 \right] > \epsilon/2 - \epsilon'$ for all sufficiently large $n \in \mathbb{N}$ where $KL(D_n \; || \; D_{\mathcal{M}_n}) < (1 - \epsilon)n$.
\end{claim*}

\begin{proof}
This follows from the assumption that $KL(D_n \; || \; D_{\mathcal{M}_n}) < (1 - \epsilon)n$, and thus, by data processing, that $KL((D_n)_{\leq 2n} \; || \; (D_{\mathcal{M}_n})_{\leq 2n}) < (1 - \epsilon)n$ (where $(D_n)_{\leq 2n}$ represents the distribution of the first $2n$ bits of $D_n$, and respectively for $D_{\mathcal{M}_n}$). Thus:
\[ KL((D_n)_{\leq 2n} \; || \; (D_{\mathcal{M}_n})_{\leq 2n}) = \mathbf{E}_{y \leftarrow D_n}[\log(1/D_{\mathcal{M}_n}(y, *))] - H((D_n)_{\leq 2n}) < (1 - \epsilon)n \]
and so
\[ \mathbf{E}_{x \leftarrow U_n}[\log(1/D_{\mathcal{M}_n}(g_n(x), *))] = \mathbf{E}_{y \leftarrow D_n}[\log(1/D_{\mathcal{M}_n}(y, *))] < (1 - \epsilon)n + H((D_n)_{\leq 2n}) \leq (2-\epsilon)n \]
since $H((D_n)_{\leq 2n}) \le H(D_n) = n$. Now, by construction of $\mathcal{A}$, $\mathcal{A}$ outputs $1$ whenever $\log(1/D_{\mathcal{M}_n}(y, *)) < 2n-c$; by Markov's inequality and the above bound on the expectation, the probability that this is \emph{not} true (i.e., that $\mathcal{A}$ outputs $0$) when $y$ is given by $g_n(x)$ for $x \leftarrow U_n$ can be at most $\frac{(2-\epsilon)n}{2n-c}$, so the probability that $\mathcal{A}$ outputs $1$, then, must be at least 
\[ 1 - \frac{(2-\epsilon)n}{2n-c} = \frac{\epsilon n - c}{2n - c}\]
which asymptotically approaches $\epsilon/2$ as $n \rightarrow \infty$, implying the conclusion.
\end{proof}

Given these, since we assumed by construction that $2^{-c}$ is a constant smaller than $\epsilon /2$, there is a non-negligible (constant) separation between the two probabilities for infinitely many (resp., any sufficiently large) $n$, which contradicts the assumption that $\mathcal{G}$ is a PRG (resp., infinitely-often PRG) and completes the proof.

\label{thm:owf-inverter-to-predictor-2}
If infinitely-often one-way functions do not exist, then the following is true for any $\epsilon(n) \in 1/\mathsf{poly}(n)$:

For every  family $\mathcal{D} = \lbrace D_n \rbrace_{n \in \mathbb{N}}$ distributions  and a compression scheme $(\mathsf{Enc},\mathsf{Dec})$ with efficient encoding and decoding that is $\delta$-optimal for $\mathcal{D}$, there exists an efficiently computable autoregressive models $\lbrace \mathcal{M}_n \rbrace_{n \in \mathbb{N}}$ where, for any $n \in \mathbb{N}$ the respective model $\mathcal{M}_n$ is $\epsilon(n)$-approximately $\delta(n)$-optimal with respect to $D_n$.

\label{def:pseudoentropy}
Given jointly distributed families of random variables $\mathcal{X} = \lbrace X_n \rbrace_{n \in \mathbb{N}}$ and $\mathcal{B} = \lbrace B_n \rbrace_{n \in \mathbb{N}}$, where $\mathcal{B}$ takes values in $\lbrace 0,1 \rbrace$, we say that $\mathcal{B}$ has (non-uniform) \textbf{conditional pseudoentropy} at least $h(\cdot)$ given $X$ if, for any polynomial $p(\cdot)$, there exists a $\lbrace 0,1 \rbrace$-valued family $\mathcal{C} = \lbrace C_n \rbrace_{n \in \mathbb{N}}$ of random variables jointly distributed with $(\mathcal{X}, \mathcal{B})$ such that:
\begin{enumerate}
    \item For all sufficiently large $n \in \mathbb{N}$, $H(C_n | X_n) \geq h(n) - 1/p(n)$
    \item The families $(\mathcal{X}, \mathcal{B})$ and $(\mathcal{X}, \mathcal{C})$ are computationally indistinguishable.\footnote{That is, for any efficient non-uniform distinguisher $D$, there exists negligible $\epsilon(\cdot)$ such that, for all sufficiently large $n \in \mathbb{N}$, $\text{Pr} \left[(x, b) \leftarrow (X_n, B_n): D(1^n, x, b) = 1 \right]$ and $\text{Pr} \left[(x, c) \leftarrow (X_n, C_n): D(1^n, x, c) = 1 \right]$ differ by no more than $\epsilon(n)$.}
\end{enumerate}

Given a polynomial $m(\cdot)$ and family of random variables $\mathcal{B} = \lbrace B_n \rbrace_{n \in \mathbb{N}}$ where $B_n$ takes values in $\lbrace 0,1 \rbrace^{m(n)}$, we say that $\mathcal{B}$ has (non-uniform) \textbf{next-bit pseudoentropy} at least $h(\cdot)$ if, letting family $\mathcal{I} = \lbrace I_n \rbrace_{n \in \mathbb{N}}$ be such that $I_n$ is uniformly distributed over $[m(n)]$, then the conditional pseudoentropy of the family $\lbrace (B_n)_{I_n} \rbrace_{n \in \mathbb{N}}$ given $\lbrace (B_n)_{<I_n} \rbrace_{n \in \mathbb{N}}$ is at least $h(n)/m(n)$.

\label{cor:incompressibility-pseudoentropy}
Given polynomial maximum length $m(\cdot)$ and family of distributions $\mathcal{D} = \lbrace D_n \rbrace_{n \in \mathbb{N}}$ where $D_n$ is a distribution over $\lbrace 0,1 \rbrace^{m(n)}$, if, for some function $k(\cdot)$, $\mathcal{D}$ cannot be monotonically compressed to length $k(n)$ infinitely often (namely, for any efficient, monotone, prefix-free encoding $\mathsf{Enc}$, $E_{x\gets \mathcal{D}_n}[len(\mathsf{Enc}(x))]\ge k(n)$ for all but finitely many $n \in \mathbb{N}$),

then $\mathcal{D}$ has next-bit pseudoentropy at least $k(n)-2$.
